## Why This Is Asked
Tests ability to design a streaming data pipeline with on-the-fly validation and data sanitization without loading all data in memory.

## Key Concepts
- Streaming generators
- Input validation and error handling
- PII masking strategies
- In-place data transformation with O(1) extra memory

## Code Example
```javascript
def sanitize_events(stream):
    import json
    for line in stream:
        try:
            obj = json.loads(line)
        except Exception:
            continue
        if not isinstance(obj, dict):
            continue
        if not all(k in obj for k in ("user_id","email","action","ts")):
            continue
        if not isinstance(obj["user_id"], str):
            continue
        if not isinstance(obj["email"], str):
            continue
        if not isinstance(obj["action"], str):
            continue
        if not isinstance(obj["ts"], int):
            continue
        email = obj["email"]
        local, _, domain = email.partition("@")
        if len(local) <= 2:
            masked_local = "*" * len(local)
        else:
            masked_local = local[0] + "*" * (len(local) - 2) + local[-1]
        masked_email = masked_local + "@" + domain
        out = {"user_id": obj["user_id"], "email": masked_email, "action": obj["action"], "ts": obj["ts"]}
        if "phone" in obj:
            out["phone"] = "REDACTED"
        yield out
```

## Why This Is Asked
This question tests data normalization, type coercion, and error reporting using Python basics.

## Key Concepts
- Dataclasses for lightweight models
- Type hints and basic validation
- ISO 8601 parsing with datetime
- Error aggregation for batch records

## Code Example
```python
from dataclasses import dataclass
from datetime import datetime
from typing import List, Dict, Any

@dataclass
class User:
    id: int
    name: str
    signup_ts: datetime
    is_active: bool

def _to_int(v: Any) -> int:
    if isinstance(v, int):
        return v
    return int(v)

def _parse_ts(ts: Any) -> datetime:
    if isinstance(ts, datetime):
        return ts
    return datetime.fromisoformat(ts)

def _to_bool(v: Any) -> bool:
    if isinstance(v, bool):
        return v
    if isinstance(v, str):
        return v.strip().lower() in {"true", "1", "yes", "y"}
    return bool(v)


def normalize_users(users: List[Dict[str, Any]]) -> List[User]:
    out: List[User] = []
    bad: List[int] = []
    for i, rec in enumerate(users):
        try:
            u = User(
                id=_to_int(rec.get("id")),
                name=rec.get("name", ""),
                signup_ts=_parse_ts(rec.get("signup_ts")),
                is_active=_to_bool(rec.get("is_active", False)),
            )
            out.append(u)
        except Exception:
            bad.append(i)
    if bad:
        raise ValueError(f"Invalid records at indices: {bad}")
    return out
```

